import heapq

def shortest_path(edges, start, end):
    """
    Find the shortest path between two nodes in a directed weighted graph.

    Args:
        edges: List of tuples (from_node, to_node, weight)
        start: Starting node
        end: Ending node

    Returns:
        Tuple of (distance, path), or (None, None) if no path exists

    Raises:
        ValueError: If any edge has a negative weight
    """
    # Handle case where start equals end
    if start == end:
        return (0, [start])

    # Collect all unique nodes from edges
    all_nodes = set()
    for from_node, to_node, _ in edges:
        all_nodes.add(from_node)
        all_nodes.add(to_node)

    # Validate that both start and end exist in graph
    if start not in all_nodes or end not in all_nodes:
        return (None, None)

    # Build adjacency list
    adj = {}
    has_negative = False
    for from_node, to_node, weight in edges:
        if weight < 0:
            raise ValueError("Negative edge weight detected")

        if from_node not in adj:
            adj[from_node] = []
        adj[from_node].append((to_node, weight))

    # Ensure start node exists in the adjacency list; add it if needed
    if start not in adj:
        adj[start] = []

    # Dijkstra's algorithm
    distances = {node: float('inf') for node in all_nodes}
    predecessors = {}
    distances[start] = 0
    pq = [(0, start)]
    visited = set()

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        if current_node in visited:
            continue
        visited.add(current_node)

        if current_node == end:
            break

        for neighbor, weight in adj.get(current_node, []):
            if neighbor not in visited:
                new_dist = current_dist + weight
                if new_dist < distances[neighbor]:
                    distances[neighbor] = new_dist
                    predecessors[neighbor] = current_node
                    heapq.heappush(pq, (new_dist, neighbor))

    # Check if end was reached
    if distances[end] == float('inf'):
        return (None, None)

    # Reconstruct path from end to start
    path = []
    current = end
    while current is not None:
        path.append(current)
        current = predecessors.get(current)

    path.reverse()
    return (distances[end], path)
